CREATE TABLE "ContactMessage" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT, "subject" TEXT, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ContactMessage_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ContactMessage_status_createdAt_idx" ON "ContactMessage"("status", "createdAt");
CREATE TABLE "SponsorInquiry" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT, "country" TEXT, "amount" TEXT, "frequency" TEXT, "message" TEXT, "status" TEXT NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SponsorInquiry_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SponsorInquiry_status_createdAt_idx" ON "SponsorInquiry"("status", "createdAt");
CREATE TABLE "NewsletterSubscriber" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "NewsletterSubscriber_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "NewsletterSubscriber_email_key" ON "NewsletterSubscriber"("email");
CREATE TABLE "SiteSettings" ("id" TEXT NOT NULL DEFAULT 'main', "ministryName" TEXT NOT NULL DEFAULT 'Papa’s Love Children Ministry', "email" TEXT NOT NULL DEFAULT 'papaslovechildrenministry@gmail.com', "phone" TEXT NOT NULL DEFAULT '+256 774615784', "alternatePhone" TEXT NOT NULL DEFAULT '+256709196703', "location" TEXT NOT NULL DEFAULT 'Naama Village, Mityana, Uganda', "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id"));
